INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'External Iliac Vein (EIV)', 'Curvilinear 2–5 MHz; patient supine', '[{"id":"venous_eiv_0","label":"Transverse compression at inguinal ligament level","detail":"Compress every 2 cm along the vessel course","critical":true},{"id":"venous_eiv_1","label":"Longitudinal color Doppler — confirm flow, respiratory phasicity","detail":"","critical":false},{"id":"venous_eiv_2","label":"Spectral Doppler — phasic waveform with respiration","detail":"Loss of phasicity suggests proximal obstruction (iliac or IVC)","critical":false}]', 0) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'Common Femoral Vein (CFV)', 'Linear 5–12 MHz; patient supine, hip externally rotated', '[{"id":"venous_cfv_0","label":"Transverse compression at inguinal crease","detail":"Vessel should fully collapse with gentle probe pressure","critical":true},{"id":"venous_cfv_1","label":"Longitudinal color Doppler — augmentation with calf squeeze","detail":"","critical":false},{"id":"venous_cfv_2","label":"Spectral Doppler — phasic waveform, Valsalva response","detail":"","critical":false},{"id":"venous_cfv_3","label":"Saphenofemoral junction (SFJ) — assess for reflux if indicated","detail":">0.5 s reflux on Valsalva = significant","critical":false}]', 1) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'Femoral Vein (FV) / Superficial Femoral Vein', 'Linear 5–12 MHz; patient supine', '[{"id":"venous_fv_0","label":"Compression every 2–3 cm from CFV to adductor canal","detail":"","critical":true},{"id":"venous_fv_1","label":"Color Doppler throughout — note any filling defects","detail":"","critical":false},{"id":"venous_fv_2","label":"Spectral Doppler at mid-thigh level","detail":"","critical":false}]', 2) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'Popliteal Vein (PopV)', 'Linear 5–12 MHz; patient prone or lateral decubitus', '[{"id":"venous_pop_0","label":"Transverse compression at popliteal fossa","detail":"","critical":true},{"id":"venous_pop_1","label":"Color Doppler — augmentation with foot dorsiflexion","detail":"","critical":false},{"id":"venous_pop_2","label":"Identify popliteal artery (pulsatile) adjacent to vein","detail":"","critical":false}]', 3) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'Calf Veins (Tibial / Peroneal)', 'Linear 5–12 MHz; patient prone or lateral decubitus', '[{"id":"venous_calf_0","label":"Anterior tibial, posterior tibial, and peroneal veins — compression bilaterally","detail":"Calf DVT extends to popliteal in ~20% — follow-up in 5–7 days if isolated","critical":false},{"id":"venous_calf_1","label":"Gastrocnemius and soleal sinuses — assess for muscular vein thrombosis","detail":"","critical":false}]', 4) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);
INSERT INTO navigatorOverrides (module, sectionName, probe, items, sortOrder) VALUES ('venous', 'Great Saphenous Vein (GSV)', 'Linear 5–12 MHz; patient supine or standing', '[{"id":"venous_gsv_0","label":"GSV diameter at SFJ and mid-thigh — document for ablation planning","detail":">3 mm at SFJ with reflux = significant insufficiency","critical":false},{"id":"venous_gsv_1","label":"Reflux assessment: Valsalva at SFJ; cuff deflation at thigh/calf","detail":">0.5 s reflux = pathologic","critical":false},{"id":"venous_gsv_2","label":"Varicosities — map distribution and perforator connections","detail":"","critical":false}]', 5) ON DUPLICATE KEY UPDATE probe=VALUES(probe), items=VALUES(items), sortOrder=VALUES(sortOrder);

